#!/usr/bin/env node
/**
 * INEX CLIENT V2.3 — Complete Core & UI Updater
 * Run inside your inex-client folder:
 *   node inex_client_installer.js
 *
 * What this fixes:
 * 1. Play Tab Subtitle -> "LIFE IS A GAME • CHOOSE YOUR LEVEL"
 * 2. Settings Tab -> Removed custom Discord status input & custom logo upload button (kept Discord toggle & Frosted Glass slider)
 * 3. Accounts -> Skins & Capes 3D Preview -> 60 FPS animated 3D character + properly proportioned waving cape (supports custom uploaded PNGs)
 * 4. Direct In-Game Skin & Cape -> Injects inex-cosmetics-override.jar at Index 0 of -cp + JVM agent so skins & capes show directly in-game without enabling Resource Packs
 * 5. Core Loader Fix -> Quilt, Forge, and NeoForge resolve & launch their true mod loader runtimes (never falling back to Fabric or Vanilla)
 */
const fs = require('fs');
const path = require('path');
const os = require('os');

const FILES = {
  "README.md": "",
  "build-exe.bat": "",
  "main.js": "",
  "package.json": "",
  "preload.js": "",
  "start-launcher.bat": "",
  ".vscode/tasks.json": "",
  "src/index.html": "",
  "src/inex-logo.png": "",
  "src/renderer.js": "",
  "src/style.css": "",
  "src/main/accountManager.js": "",
  "src/main/discordRpcManager.js": "",
  "src/main/installer.js": "",
  "src/main/javaManager.js": "",
  "src/main/launcher.js": "",
  "src/main/loaderManager.js": "",
  "src/main/modrinthManager.js": "",
  "src/main/profileManager.js": "",
  "src/main/settingsManager.js": "",
  "src/main/versionManager.js": "",
  "src/main/zipUtils.js": "",
  "src/default-mods/inex-cosmetics-agent.jar": "",
  "test/test-backend.js": ""
};

const targetRoot = process.cwd();
console.log('==========================================================');
console.log('  INEX CLIENT V2.3 — CORE & UI UPDATER');
console.log('  Target Directory: ' + targetRoot);
console.log('==========================================================');

const appData = process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming');
const inexDataDir = path.join(appData, 'InexClient');
const dotInexDir = path.join(appData, '.inexclient');

// Clean up any stale legacy effective.json caches in %APPDATA%\.inexclient\versions
const versionsDir = path.join(dotInexDir, 'versions');
if (fs.existsSync(versionsDir)) {
  try {
    for (const v of fs.readdirSync(versionsDir)) {
      const vPath = path.join(versionsDir, v);
      if (fs.statSync(vPath).isDirectory()) {
        for (const f of fs.readdirSync(vPath)) {
          if (f === 'effective.json' || (f.startsWith('effective-') && f !== 'effective-fabric.json' && f !== 'effective-vanilla.json')) {
            try {
              fs.unlinkSync(path.join(vPath, f));
              console.log('  [CLEANED STALE CACHE] versions/' + v + '/' + f);
            } catch (_) {}
          }
        }
      }
    }
  } catch (_) {}
}

// Clear any customLogoDataUrl in settings.json so default logo stays permanent
const settingsFile = path.join(inexDataDir, 'settings.json');
if (fs.existsSync(settingsFile)) {
  try {
    const s = JSON.parse(fs.readFileSync(settingsFile, 'utf8'));
    s.customLogoDataUrl = '';
    s.discordStatusText = 'INEX CLIENT • Windows Edition';
    fs.writeFileSync(settingsFile, JSON.stringify(s, null, 2), 'utf8');
  } catch (_) {}
}

for (const [relPath, b64] of Object.entries(FILES)) {
  const fullPath = path.join(targetRoot, relPath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, Buffer.from(b64, 'base64'));
  console.log('  [UPDATED] ' + relPath);
}

fs.mkdirSync(path.join(targetRoot, 'src', 'default-mods', 'universal'), { recursive: true });
console.log('==========================================================');
console.log('  [SUCCESS] All Core & UI Fixes Applied!');
console.log('  Run "npm start" (or "electron .") to test, or "build-exe.bat" to build!');
console.log('==========================================================');
